{
  "name": "opencode-subagents-sidebar",
  "version": "0.1.6",
  "description": "OpenCode TUI sidebar that lists the current session's subagent sessions and opens one on click.",
  "type": "module",
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "tsconfig.json"
  ],
  "keywords": [
    "opencode-plugin",
    "opencode",
    "tui",
    "subagents",
    "sidebar"
  ],
  "license": "MIT",
  "author": "Ger Moran",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/germoran1-debug/opencode-subagents-sidebar.git"
  },
  "homepage": "https://github.com/germoran1-debug/opencode-subagents-sidebar#readme",
  "bugs": {
    "url": "https://github.com/germoran1-debug/opencode-subagents-sidebar/issues"
  },
  "dependencies": {
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.1.2"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "^2.1.2",
    "@opentui/core": "^0.6.6",
    "@opentui/solid": "^0.6.6",
    "typescript": "^5.9.3"
  }
}
